using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "ConfigMcpServer",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns the full application configuration")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        MimeType = "application/json"), Description("Returns current feature flag states")]
    public static string GetFeatureFlags() =>
        JsonSerializer.Serialize(AppConfig["features"], new JsonSerializerOptions { WriteIndented = true });
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Checks whether a specific feature flag is enabled")]
    public static string CheckFeatureFlag(
        [Description("Name of the feature flag to check (e.g., darkMode, notifications, betaFeatures)")] string flagName)
    {
        var features = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        };

        return features.TryGetValue(flagName, out var enabled)
            ? $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}."
            : $"Feature '{flagName}' not found. Available flags: {string.Join(", ", features.Keys)}";
    }

    [McpServerTool, Description("Returns the current server uptime and status")]
    public static string GetServerStatus()
    {
        return $"Server is running. Started at {System.Diagnostics.Process.GetCurrentProcess().StartTime:u}";
    }
}

